-- Complete lessons 21-30 with bilingual rules, tips, quizzes and matching media.
BEGIN;
WITH data (lesson_number,summary_nl,summary_fa,rule_nl,rule_fa,tip_nl,tip_fa,image_src,question_nl,question_fa,option_1_nl,option_1_fa,option_2_nl,option_2_fa,option_3_nl,option_3_fa,correct_option,explanation_nl,explanation_fa) AS (VALUES
 (21,'De maximumsnelheid is een bovengrens; omstandigheden kunnen een lagere snelheid noodzakelijk maken.','حداکثر سرعت یک مرز بالاست؛ شرایط ممکن است سرعت پایین‌تر را لازم کند.','Volg borden en algemene snelheidsregels, maar rijd nooit sneller dan veilig is voor zicht, wegdek en verkeer.','تابلوها و قواعد عمومی سرعت را رعایت کنید، اما هرگز سریع‌تر از حد ایمن برای دید، سطح راه و ترافیک نروید.','Een maximumsnelheid is geen verplichte snelheid. Bij gevaar vertraag je ook als je onder de limiet rijdt.','حداکثر سرعت، سرعت اجباری نیست. در خطر حتی اگر زیر حد هستید آهسته‌تر بروید.','/images/Blauwe auto bij 50-km-bord.jpg','Mag je altijd met de aangegeven maximumsnelheid rijden?','آیا همیشه می‌توانید با حداکثر سرعت اعلام‌شده بروید؟','Ja, ongeacht de situatie','بله، بدون توجه به وضعیت','Nee, alleen als de omstandigheden dat veilig toelaten','خیر، فقط اگر شرایط ایمن باشد','Alleen als er verkeer achter je rijdt','فقط اگر پشت سر ترافیک باشد',1,'De limiet is een bovengrens; je snelheid moet ook aan de actuele omstandigheden zijn aangepast.','حد سرعت مرز بالاست و سرعت باید با شرایط فعلی نیز سازگار باشد.'),
 (22,'Een veilige snelheid laat je stoppen binnen de afstand die je kunt overzien en die vrij is.','سرعت ایمن اجازه می‌دهد در فاصله قابل دید و آزاد توقف کنید.','Pas snelheid voortdurend aan zicht, bochten, kruispunten, wegdek, weer en kwetsbare weggebruikers aan.','سرعت را پیوسته با دید، پیچ، تقاطع، سطح راه، هوا و کاربران آسیب‌پذیر هماهنگ کنید.','Vraag niet alleen wat toegestaan is, maar vooral of je nog tijd en ruimte hebt om op onverwacht gevaar te reageren.','فقط نپرسید چه سرعتی مجاز است؛ ببینید برای واکنش به خطر ناگهانی زمان و جا دارید یا نه.','/images/theory-015-stopping-distance.webp','Wanneer is je snelheid veilig gekozen?','چه زمانی سرعت شما ایمن انتخاب شده است؟','Als je binnen de zichtbare vrije afstand kunt stoppen','اگر بتوانید در فاصله آزاد و قابل دید توقف کنید','Als je precies de limiet rijdt','اگر دقیقاً حد سرعت بروید','Als je sneller rijdt dan het verkeer achter je','اگر از ترافیک پشت سر سریع‌تر بروید',0,'Je moet kunnen stoppen binnen de afstand die je kunt overzien en die vrij is.','باید بتوانید در فاصله‌ای که می‌بینید و آزاد است توقف کنید.'),
 (23,'De reactieafstand is de afstand die je aflegt tussen het zien van gevaar en het beginnen met remmen.','فاصله واکنش مسافتی است که از دیدن خطر تا آغاز ترمز طی می‌کنید.','Een hogere snelheid, vermoeidheid, alcohol en afleiding vergroten de afstand voordat je daadwerkelijk remt.','سرعت بیشتر، خستگی، الکل و حواس‌پرتی فاصله پیش از ترمز واقعی را افزایش می‌دهد.','Verdubbel je de snelheid, dan wordt de reactieafstand bij dezelfde reactietijd ongeveer twee keer zo groot.','اگر سرعت دو برابر شود، با زمان واکنش یکسان فاصله واکنش تقریباً دو برابر می‌شود.','/images/Reactie en remweg bij een obstakel.jpg','Wat vergroot de reactieafstand?', 'چه چیزی فاصله واکنش را بیشتر می‌کند؟','Lagere snelheid en volledige aandacht','سرعت کمتر و توجه کامل','Afleiding en hogere snelheid','حواس‌پرتی و سرعت بیشتر','Een droge weg','راه خشک',1,'Afleiding vertraagt je reactie en bij hogere snelheid leg je iedere seconde meer meters af.','حواس‌پرتی واکنش را کند می‌کند و در سرعت بالاتر هر ثانیه مترهای بیشتری طی می‌کنید.'),
 (24,'De remweg begint wanneer je remt en eindigt wanneer het voertuig stilstaat.','مسافت ترمز از آغاز ترمز تا توقف کامل وسیله است.','Snelheid, banden, remmen, belading en grip op het wegdek bepalen samen hoe lang de remweg wordt.','سرعت، تایر، ترمز، بار و چسبندگی راه باهم طول مسافت ترمز را تعیین می‌کنند.','De remweg groeit veel sterker dan de snelheid: twee keer zo snel betekent ongeveer vier keer zoveel remweg.','مسافت ترمز بسیار بیشتر از سرعت رشد می‌کند؛ دو برابر سرعت تقریباً چهار برابر مسافت ترمز می‌دهد.','/images/Reactie en remweg bij een obstakel.jpg','Wat gebeurt ongeveer met de remweg als de snelheid verdubbelt?', 'اگر سرعت دو برابر شود تقریباً چه اتفاقی برای مسافت ترمز می‌افتد؟','Die blijft gelijk','برابر می‌ماند','Die wordt ongeveer twee keer zo lang','تقریباً دو برابر می‌شود','Die wordt ongeveer vier keer zo lang','تقریباً چهار برابر می‌شود',2,'De remweg neemt ongeveer toe met het kwadraat van de snelheid.','مسافت ترمز تقریباً با مربع سرعت افزایش می‌یابد.'),
 (25,'De stopafstand bestaat uit reactieafstand plus remweg.','فاصله توقف برابر فاصله واکنش به اضافه مسافت ترمز است.','Houd rekening met beide delen: je legt al afstand af voordat je voet de rem bedient.','هر دو بخش را در نظر بگیرید؛ پیش از فشار دادن ترمز نیز مسافت طی می‌کنید.','Meer snelheid vergroot zowel de reactieafstand als de remweg en maakt de totale stopafstand veel langer.','سرعت بیشتر هم فاصله واکنش و هم مسافت ترمز را زیاد و فاصله توقف را بسیار طولانی می‌کند.','/images/theory-015-stopping-distance.webp','Waaruit bestaat de stopafstand?', 'فاصله توقف از چه چیزهایی تشکیل می‌شود؟','Alleen de remweg','فقط مسافت ترمز','Reactieafstand plus remweg','فاصله واکنش به اضافه مسافت ترمز','Alleen de volgafstand','فقط فاصله تعقیب',1,'Eerst reageert de bestuurder en daarna remt het voertuig; beide afstanden vormen samen de stopafstand.','ابتدا راننده واکنش نشان می‌دهد و سپس وسیله ترمز می‌کند؛ مجموع آن‌ها فاصله توقف است.'),
 (26,'Voldoende volgafstand geeft tijd om te reageren en gecontroleerd te remmen.','فاصله تعقیب کافی برای واکنش و ترمز کنترل‌شده زمان می‌دهد.','Gebruik bij normale omstandigheden minstens ongeveer twee seconden afstand en vergroot die bij extra risico.','در شرایط عادی حداقل حدود دو ثانیه فاصله بگیرید و در خطر بیشتر آن را افزایش دهید.','Kies een vast punt waar de voorligger passeert en tel rustig twee seconden tot je dat punt zelf bereikt.','یک نقطه ثابت انتخاب کنید و پس از عبور موتر جلویی تا رسیدن خودتان آرام دو ثانیه بشمارید.','/images/theory-014-following-distance.webp','Welke vuistregel helpt bij normale omstandigheden voor voldoende volgafstand?', 'در شرایط عادی کدام قاعده برای فاصله تعقیب کمک می‌کند؟','Ongeveer twee seconden','حدود دو ثانیه','Een halve seconde','نیم ثانیه','Altijd precies vijf meter','همیشه دقیقاً پنج متر',0,'De tweesecondenregel past de afstand automatisch aan je snelheid aan; bij slecht weer neem je meer.', 'قاعده دو ثانیه فاصله را با سرعت هماهنگ می‌کند؛ در هوای بد فاصله بیشتری بگیرید.'),
 (27,'Regen vermindert zicht en grip en verlengt de remweg.','باران دید و چسبندگی را کم و مسافت ترمز را طولانی می‌کند.','Verminder geleidelijk snelheid, vergroot de volgafstand en voorkom hard remmen of abrupt sturen.','سرعت را آرام کم کنید، فاصله را بیشتر کنید و از ترمز یا فرمان ناگهانی بپرهیزید.','Bij veel water kan aquaplaning ontstaan; laat dan rustig gas los en houd het stuur stabiel.','در آب زیاد لغزش آبی ممکن است رخ دهد؛ آرام گاز را رها و فرمان را ثابت نگه دارید.','/images/Grote volgafstand in zware regen.jpg','Wat doe je met de volgafstand bij zware regen?', 'در باران شدید با فاصله تعقیب چه می‌کنید؟','Kleiner maken','کمتر می‌کنید','Gelijk houden','همان نگه می‌دارید','Duidelijk vergroten','به‌طور واضح بیشتر می‌کنید',2,'Door minder zicht en grip heb je bij regen meer tijd en afstand nodig.', 'به علت دید و چسبندگی کمتر در باران زمان و فاصله بیشتری لازم دارید.'),
 (28,'In mist pas je snelheid aan de korte zichtafstand aan en houd je extra afstand.','در مه سرعت را با دید کوتاه هماهنگ و فاصله بیشتری نگه می‌دارید.','Gebruik dimlicht; mistlicht vóór mag bij ernstig belemmerd zicht en mistachterlicht alleen bij minder dan 50 meter zicht door mist of sneeuw.','چراغ پایین را استفاده کنید؛ مه‌شکن جلو در دید بسیار کم و مه‌شکن عقب فقط زیر ۵۰ متر دید در مه یا برف مجاز است.','Groot licht werkt in mist vaak slechter doordat het licht terugkaatst en je verblindt.','نوربالا در مه معمولاً بدتر است چون بازتاب می‌شود و شما را خیره می‌کند.','/images/Mistachterlicht bij 50 meter zicht.jpg','Wanneer mag het mistachterlicht worden gebruikt?', 'چه زمانی می‌توان از چراغ مه‌شکن عقب استفاده کرد؟','Bij minder dan 50 meter zicht door mist of sneeuw','وقتی دید در مه یا برف کمتر از ۵۰ متر است','Bij iedere regenbui','در هر بارندگی','Altijd in het donker','همیشه در تاریکی',0,'Het mistachterlicht is alleen toegestaan bij minder dan 50 meter zicht door mist of sneeuw, niet bij regen.', 'چراغ مه‌شکن عقب فقط در دید کمتر از ۵۰ متر به علت مه یا برف مجاز است، نه باران.'),
 (29,'In woongebieden let je extra op kinderen, voetgangers, fietsers en onverwachte bewegingen.','در مناطق مسکونی به کودکان، عابران، دوچرخه‌سواران و حرکت ناگهانی توجه ویژه کنید.','Volg de aangegeven zone- of erfsnelheid en kies bij weinig overzicht een nog lagere veilige snelheid.','سرعت منطقه یا حیاط را رعایت کنید و در دید کم سرعت ایمن پایین‌تری انتخاب کنید.','In een erf geldt stapvoets verkeer met maximaal 15 km/u en mogen voetgangers de volle breedte gebruiken.','در حیاط مشترک حرکت بسیار آهسته با حداکثر ۱۵ کیلومتر است و عابران می‌توانند از تمام عرض استفاده کنند.','/images/theory-011-zone-30.webp','Wat is de maximumsnelheid in een erf?', 'حداکثر سرعت در حیاط مشترک چقدر است؟','15 km/u','۱۵ کیلومتر در ساعت','30 km/u','۳۰ کیلومتر در ساعت','50 km/u','۵۰ کیلومتر در ساعت',0,'In een erf geldt maximaal 15 km/u.', 'در حیاط مشترک حداکثر سرعت ۱۵ کیلومتر در ساعت است.'),
 (30,'Op autosnelwegen geldt overdag van 06.00 tot 19.00 uur in beginsel maximaal 100 km/u, tenzij borden een lagere limiet tonen.','در بزرگراه‌ها از ساعت ۶ تا ۱۹ اصولاً حداکثر ۱۰۰ کیلومتر است، مگر تابلو سرعت پایین‌تری نشان دهد.','Lees altijd de actuele borden en matrixsignalen; zij kunnen door tijdstip, drukte of werkzaamheden een andere limiet aangeven.','همیشه تابلوها و علایم ماتریسی فعلی را بخوانید؛ زمان، شلوغی یا کار جاده می‌تواند حد دیگری تعیین کند.','Een matrixbord met een lagere snelheid geldt direct, ook als een vast bord eerder een hogere snelheid aangaf.','تابلوی ماتریسی با سرعت پایین‌تر فوراً معتبر است، حتی اگر تابلوی ثابت قبلی سرعت بالاتر داشت.','/images/Snelweg met matrixbord 80 en bord 100.jpg','Wat is overdag van 06.00 tot 19.00 uur de algemene maximumsnelheid op een autosnelweg als borden niets anders aangeven?', 'از ساعت ۶ تا ۱۹ حد عمومی سرعت بزرگراه، اگر تابلو چیز دیگری نگوید، چقدر است؟','80 km/u','۸۰ کیلومتر در ساعت','100 km/u','۱۰۰ کیلومتر در ساعت','130 km/u','۱۳۰ کیلومتر در ساعت',1,'Overdag geldt als algemene bovengrens 100 km/u; volg altijd lagere aangegeven snelheden.', 'در روز حد عمومی ۱۰۰ کیلومتر است؛ سرعت پایین‌تر اعلام‌شده را همیشه رعایت کنید.')
),release AS(SELECT id FROM content_releases WHERE version=1)
UPDATE course_lessons lesson SET summary=jsonb_build_object('nl',data.summary_nl,'fa',data.summary_fa),content_blocks=jsonb_build_array(
 jsonb_build_object('type','rule','text',jsonb_build_object('nl',data.rule_nl,'fa',data.rule_fa)),
 jsonb_build_object('type','exam_tip','text',jsonb_build_object('nl',data.tip_nl,'fa',data.tip_fa)),
 jsonb_build_object('type','quiz','question',jsonb_build_object('nl',data.question_nl,'fa',data.question_fa),'options',jsonb_build_array(jsonb_build_object('nl',data.option_1_nl,'fa',data.option_1_fa),jsonb_build_object('nl',data.option_2_nl,'fa',data.option_2_fa),jsonb_build_object('nl',data.option_3_nl,'fa',data.option_3_fa)),'correctOption',data.correct_option,'explanation',jsonb_build_object('nl',data.explanation_nl,'fa',data.explanation_fa))),media=jsonb_build_array(jsonb_build_object('type','image','src',data.image_src,'alt',lesson.title)),updated_at=NOW() FROM data,release WHERE lesson.release_id=release.id AND lesson.lesson_number=data.lesson_number;
DO $check$ DECLARE n integer; BEGIN SELECT count(*) INTO n FROM course_lessons WHERE release_id=(SELECT id FROM content_releases WHERE version=1) AND lesson_number BETWEEN 21 AND 30 AND content_blocks->2->>'type'='quiz'; IF n<>10 THEN RAISE EXCEPTION 'Speed lessons validation failed: %',n; END IF; END $check$;
INSERT INTO schema_migrations(version,name) VALUES(11,'speed_distance_lessons') ON CONFLICT(version) DO NOTHING;
COMMIT;

